// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"ethereum":{"slug":"ethereum","cat":"basics","en":"Ethereum (ETH)","contentLocale":"ja","term":"イーサリアム（ETH）","aka":["ETH","Ethereum","イーサ"],"short":"イーサリアム（ETH）とは、スマートコントラクトを実行できるブロックチェーンと、その手数料の支払いやステーキングに使われるネイティブ暗号資産ETHのことです。","body":[[["ビットコイン","bitcoin"],"が主に価値の移転に特化しているのに対し、イーサリアムはプログラム（",["スマートコントラクト","smart-contract"],"）を",["ブロックチェーン","blockchain"],"上で動かせるのが特徴です。",["DeFi（分散型金融）","defi"],"、",["NFT","nft"],"、",["ステーブルコイン","stablecoin"],"など、多くのサービスがイーサリアム上で動いています。"],"ネットワークを使うときはガス代をETHで支払います。2022年9月の「The Merge」でプルーフ・オブ・ワークからプルーフ・オブ・ステークに移行し、現在はETHをステークしたバリデーターがブロックを提案・検証しています。","取引が集中するとガス代が高くなるため、Arbitrum、Optimism、Baseなどのレイヤー2で安く取引する方法も広く使われています。ETHを出金するときは、送り先がイーサリアム本体なのかレイヤー2なのか、ネットワークを必ず確認しましょう。"],"example":"例えば、ガス価格が20 gwei（1 gwei = 0.000000001 ETH）のときに、ガス使用量21,000の単純なETH送金をすると、手数料は20 × 21,000 = 420,000 gwei、つまり0.00042 ETHです。1 ETH = 40万円なら約168円になります。トークンのスワップなど複雑な処理ではガス使用量が増え、手数料も高くなります。","mistakes":["ETHを持たずにイーサリアム上のトークンを送ろうとして、ガス代が払えず送金できないこと。","取引所からの出金時に、イーサリアム本体とレイヤー2のネットワークを取り違えること。","ステーキングすればETHの価格下落リスクもなくなると誤解すること。"],"faq":[{"q":"イーサリアムとビットコインの違いは何ですか？","a":"ビットコインは主に価値の保存や送金に使われ、イーサリアムはスマートコントラクトでさまざまなアプリを動かせる基盤です。合意形成の方式も、ビットコインはPoW、イーサリアムはPoSです。"},{"q":"イーサリアムに発行上限はありますか？","a":"ETHには固定の発行上限がありません。ただし取引手数料の一部が焼却（バーン）される仕組みがあり、発行量と焼却量のバランスで供給量が増減します。"},{"q":"イーサリアムのガス代はなぜ変動するのですか？","a":"1ブロックで処理できる量には限りがあり、利用が集中すると手数料が上がるためです。混雑していない時間帯やレイヤー2を使うと安く済む場合があります。"}],"title":"イーサリアム（ETH）とは？特徴とガス代の仕組み","description":"イーサリアムの特徴、スマートコントラクト、ガス代の計算方法、PoSへの移行の意味を初心者向けに解説します。","related":[["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"],["gas-fee","ガス代（Gas fee）","ガス代とは、イーサリアムなどのブロックチェーンで送金やスマートコントラクトを実行するときに、ネットワークに支払う手数料のことです。"],["proof-of-stake","プルーフ・オブ・ステーク（PoS）","プルーフ・オブ・ステーク（PoS）とは、暗号資産を担保として預け入れ（ステーク）したバリデーターが、ブロックの提案と検証を担うコンセンサスの仕組みです。"],["layer-2","レイヤー2（L2）","レイヤー2（L2）とは、イーサリアムなどのレイヤー1の上で取引をまとめて処理し、その結果をL1に記録することで、手数料を下げ処理を速くする仕組みです。"],["defi","DeFi（分散型金融）","DeFi（分散型金融）とは、銀行や取引所などの仲介者を通さず、ブロックチェーン上のスマートコントラクトで交換、貸し借り、利回り運用などを行う金融サービスの総称です。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"layer-1":{"slug":"layer-1","cat":"basics","en":"Layer 1 (L1)","contentLocale":"ja","term":"レイヤー1（L1）","aka":["L1","Layer 1"],"short":"レイヤー1（L1）とは、ビットコイン、イーサリアム、ソラナのように、独自のネットワークで取引の検証と記録を完結させる基盤となるブロックチェーンのことです。","body":[["レイヤー1は、自前のコンセンサスの仕組み（PoWやPoSなど）とネイティブコインを持ち、取引の最終的な確定をそのチェーン自身で行います。その上に構築され、処理の一部を外に出して手数料を下げる仕組みが",["レイヤー2","layer-2"],"です。"],[["ブロックチェーン","blockchain"],"には、分散性・安全性・処理能力の3つを同時に高めるのが難しいという「トリレンマ」があるとよく言われます。L1ごとに設計の優先順位が異なり、ブロック生成の速さ、手数料の水準、",["ノード","node"],"の運営に必要な機材も大きく違います。"],["取引所で入出金するとき、同じ資産でも複数のL1に対応していることがあります。例えばUSDTは",["イーサリアム","ethereum"],"、トロン、ソラナなどで発行されているため、送金元と送金先のネットワークを必ず一致させる必要があります。"]],"example":["例えば、ある取引所からUSDTを出金するとき、イーサリアム（ERC-20）の",["出金手数料","withdrawal-fee"],"が3 ",["USDT","usdt"],"、トロン（TRC-20）が1 USDTだとします。100 USDTを送るなら、手数料はそれぞれ3%と1%です。ただし、受取側がトロンに対応していなければTRC-20で送った資産は届かないため、安さだけでネットワークを選ぶことはできません。"],"mistakes":["手数料の安さだけでネットワークを選び、受取側が対応していないチェーンに送ること。","公表されている処理速度の数字だけでL1の優劣を判断すること。","L1のネイティブコインを持たずに、そのチェーン上で取引しようとすること。"],"faq":[{"q":"レイヤー1とレイヤー2の違いは何ですか？","a":"L1は取引を自ら検証・確定する基盤チェーンで、L2はL1の上で取引をまとめて処理し、その結果をL1に記録して手数料を下げる仕組みです。"},{"q":"代表的なレイヤー1には何がありますか？","a":"ビットコイン、イーサリアム、ソラナ、BNBチェーン、アバランチなどがあります。"}],"title":"レイヤー1（L1）とは？意味とレイヤー2との違い","description":"レイヤー1（L1）ブロックチェーンの意味、トリレンマ、レイヤー2との違い、入出金時のネットワーク選びの注意点を解説します。","related":[["layer-2","レイヤー2（L2）","レイヤー2（L2）とは、イーサリアムなどのレイヤー1の上で取引をまとめて処理し、その結果をL1に記録することで、手数料を下げ処理を速くする仕組みです。"],["blockchain","ブロックチェーン","ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。"],["ethereum","イーサリアム（ETH）","イーサリアム（ETH）とは、スマートコントラクトを実行できるブロックチェーンと、その手数料の支払いやステーキングに使われるネイティブ暗号資産ETHのことです。"],["gas-fee","ガス代（Gas fee）","ガス代とは、イーサリアムなどのブロックチェーンで送金やスマートコントラクトを実行するときに、ネットワークに支払う手数料のことです。"],["coin-vs-token","コインとトークンの違い","コインとトークンの違いとは、コインは独自のブロックチェーンのネイティブ資産であり、トークンは既存のブロックチェーン上でスマートコントラクトにより発行される資産だという区別です。"]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":null,"cta":false},"token-burn":{"slug":"token-burn","cat":"basics","en":"Token burn","contentLocale":"ja","term":"トークンバーン（焼却）","aka":["バーン","焼却","Token burn"],"short":"トークンバーン（焼却）とは、トークンを誰も取り出せないアドレスに送ったりコントラクトで消滅させたりして、流通から永久に取り除くことです。","body":[["バーンの方法は主に2つあります。",["秘密鍵","private-key"],"が存在しない「バーン",["アドレス","wallet-address"],"」に送る方法と、",["スマートコントラクト","smart-contract"],"の機能で供給量そのものを減らす方法です。どちらも",["ブロックチェーン","blockchain"],"に記録されるため、実際に焼却されたかを誰でも確認できます。"],["目的は供給を減らすことです。BNBのように定期的にバーンを行うトークンや、",["イーサリアム","ethereum"],"のように取引手数料の一部（基本手数料）が自動でバーンされる仕組みもあります。イーサリアムでは、ネットワークの利用が多い時期に焼却量が新規発行量を上回ることもあります。"],["ただし、バーンが価格の上昇を保証するわけではありません。焼却量が供給全体に対してごく小さければ影響は限られ、新規発行が多ければ供給は増え続けます。「大規模バーン」と宣伝されたときは、焼却量が",["流通量","circulating-supply"],"の何%なのか、もともと流通していなかったトークンではないかを確認しましょう。"]],"example":"例えば、流通量5億枚のトークンで、四半期ごとに500万枚がバーンされるとします。1回の焼却は流通量の1%で、1年で4回なら合計2,000万枚、約4%の減少です。ただし同じ期間に3,000万枚が新規発行されれば、流通量は差し引きで1,000万枚増えることになります。","mistakes":["焼却量を流通量と比べずに、「バーン」という言葉だけで判断すること。","新規発行やアンロックによる供給増を無視して、バーンの効果だけを見ること。","送金先アドレスを確認せず、自分のトークンを誤ってバーンアドレスに送ってしまうこと。"],"faq":[{"q":"バーンされたトークンは取り戻せますか？","a":"取り戻せません。バーンアドレスには秘密鍵が存在しないため、誰もそのトークンを動かせません。"},{"q":"バーンすると価格は上がりますか？","a":"需要が変わらなければ供給減は価格の支えになり得ますが、必ず上がるわけではありません。焼却量の規模と新規発行量をあわせて判断する必要があります。"}],"title":"トークンバーン（焼却）とは？仕組みと価格への影響","description":"トークンバーン（焼却）の意味と仕組み、BNBやイーサリアムの例、価格への影響を考えるときのポイントを解説します。","related":[["tokenomics","トークノミクス","トークノミクスとは、暗号資産トークンの供給量、配分、発行スケジュール、用途、焼却などをまとめた経済設計の全体像のことです。"],["circulating-supply","流通供給量","流通供給量とは、現在市場で自由に取引できる状態にある暗号資産の枚数のことで、ロック中のトークンやまだ発行されていない分は含まれません。"],["market-capitalization","時価総額（マーケットキャップ）","時価総額（マーケットキャップ）とは、暗号資産の現在価格に流通供給量を掛けた値で、その銘柄の市場規模を比べるための基本的な指標です。"],["coin-vs-token","コインとトークンの違い","コインとトークンの違いとは、コインは独自のブロックチェーンのネイティブ資産であり、トークンは既存のブロックチェーン上でスマートコントラクトにより発行される資産だという区別です。"]],"lesson":null,"coin":{"slug":"bnb","name":"BNB","symbol":"BNB"},"tool":null,"cta":false},"fud":{"slug":"fud","cat":"basics","en":"FUD","contentLocale":"ja","term":"FUD（ファッド）","aka":["ファッド"],"short":"FUDとは「Fear, Uncertainty and Doubt（恐怖・不確実性・疑念）」の略で、市場に不安を広げ、売りを誘うような情報や雰囲気のことです。","body":[["FUDには、根拠のないうわさや誇張された悪いニュースもあれば、規制強化や取引所のトラブルのように本当に重要な情報も含まれます。",["暗号資産","cryptocurrency"],"のコミュニティでは、都合の悪いニュースを何でも「FUDだ」と片付ける傾向もあるため、レッテルではなく中身で判断することが大切です。"],["情報を見分けるには、一次情報に当たるのが基本です。規制の話なら当局の発表、取引所の問題なら公式の告知、資金の動きなら",["ブロックエクスプローラー","block-explorer"],"などのオンチェーンデータを確認します。スクリーンショットだけの投稿や、出典のない「関係者によると」という話は慎重に扱いましょう。"],["FUDで急落した局面では、パニック売りが連鎖し、さらに",["レバレッジ取引","margin-trading"],"の",["強制ロスカット","liquidation"],"が重なって下落が加速することがあります。慌てて売る前に、情報の真偽と自分のポジションの状況を確認する時間を持つことが重要です。"]],"example":"例えば、「大手取引所が出金停止」という出典不明の投稿が拡散し、あるトークンが1時間で15%下落したとします。2,000ドル分を保有していれば、評価額は1,700ドルです。公式発表を確認すると定期メンテナンスだったと分かり、価格が元に戻った場合、慌てて1,700ドルで売っていた人は300ドルの損失を確定させていたことになります。","mistakes":["出典のないSNS投稿だけを根拠に保有資産を売ること。","本当に重要な悪材料まで「ただのFUD」と決めつけて無視すること。","急落時に成行で売り、薄くなった板で想定以上に不利な価格で約定すること。"],"faq":[{"q":"FUDは悪いことですか？","a":"FUDという言葉自体は状況を表すだけです。根拠のない情報もあれば実際のリスクを示す情報もあるため、一次情報で確認することが大切です。"},{"q":"FUDで下がったときは買い時ですか？","a":"一概には言えません。下落の原因が一時的なうわさなのか、根本的な問題なのかによって判断が変わります。"}],"title":"FUDとは？意味と情報の見分け方を解説","description":"暗号資産でよく使われるFUDの意味、根拠のないうわさと重要なリスク情報の見分け方、急落時に気をつけたい点を解説します。","related":[["fomo","FOMO（フォーモ）","FOMOとは「Fear Of Missing Out」の略で、値上がりに乗り遅れることへの不安から、冷静な判断をせずに買ってしまう心理のことです。"],["bear-market","弱気相場（ベアマーケット）","弱気相場（ベアマーケット）とは、価格が長期間にわたって下落傾向を続け、悲観的な見方が市場に広がっている相場のことです。"],["fear-and-greed-index","恐怖・強欲指数（Fear and Greed Index）","恐怖・強欲指数とは、価格変動率や出来高、SNSの反応などを組み合わせて、市場参加者の心理を0（極度の恐怖）から100（極度の強欲）の数値で表した指標です。"],["on-chain-analysis","オンチェーン分析","オンチェーン分析とは、ブロックチェーン上に公開されている取引記録やアドレスの残高などのデータを集計し、資金の流れや市場参加者の行動を読み解く手法のことです。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"「儲けさせてあげる」と言う人がいたら、まず何を要求しているか見極めよう"},"coin":null,"tool":null,"cta":false},"bid-ask-spread":{"slug":"bid-ask-spread","cat":"trading","en":"Bid-ask spread","contentLocale":"ja","term":"スプレッド（売買価格差）","aka":["スプレッド","ビッドアスクスプレッド","Bid-ask spread"],"short":"スプレッドとは、板の最良買い気配（ビッド）と最良売り気配（アスク）の価格差のことで、売買のたびに実質的にかかるコストの一つです。","body":["例えば、最良買い気配が99.9、最良売り気配が100.1なら、スプレッドは0.2です。すぐに買うと100.1で買い、すぐに売ると99.9で売ることになるため、買ってすぐに売るだけでスプレッドの分だけ損をします。",[["出来高","trading-volume"],"が多く板の厚い主要ペアではスプレッドが狭く、小型銘柄、取引の少ない時間帯、相場の急変時には広がりやすくなります。",["マーケットメイカー","market-maker"],"と呼ばれる業者が売りと買いの両方に注文を出すことで、スプレッドを狭く保つ役割を担っています。"],["日本の取引所の「",["販売所","instant-convert"],"」では、表示される買値と売値の差がスプレッドで、取引手数料が無料でも実質的なコストはスプレッドに含まれています。販売所のスプレッドは板取引より広いことが多いため、両方の価格を比べてから売買しましょう。"]],"example":["例えば、販売所で",["ビットコイン","bitcoin"],"の買値が1,020万円、売値が980万円と表示されていたとします。スプレッドは40万円で、中間価格の1,000万円に対して約4%です。この状態で10万円分を買ってすぐに売ると、約3,900円の損失になります。同じ時間に板取引のスプレッドが1万円（0.1%）なら、コストは約100円で済みます。"],"mistakes":["「手数料無料」という表示だけを見て、販売所のスプレッドを見落とすこと。","相場の急変でスプレッドが広がった状態のまま成行注文を出すこと。","板の中間価格を自分の約定価格だと思い込むこと。"],"faq":[{"q":"スプレッドはなぜ広がるのですか？","a":"注文が少ないときや、値動きが激しくマーケットメイカーが注文を減らしたときに、最良の買値と売値の差が開きやすくなります。"},{"q":"スプレッドのコストを抑えるにはどうすればいいですか？","a":"出来高の多いペアを選ぶ、販売所より板取引を使う、指値注文で自分の価格を指定するといった方法があります。"}],"title":"スプレッドとは？暗号資産の売買価格差と隠れコスト","description":"暗号資産のスプレッド（売買価格差）の意味、販売所と板取引の違い、スプレッドのコストを抑える方法を具体例で解説します。","related":[["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["market-maker","マーケットメイカー（MM）","マーケットメイカーとは、買い注文と売り注文の両方を板に出し続けて、他の参加者がいつでも売買できる状態を作る事業者やトレーダーのことです。"],["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"画面に表示された価格が、なぜ約定価格と違うのか？"},"coin":null,"tool":"/rates","cta":false},"slippage":{"slug":"slippage","cat":"trading","en":"Slippage","contentLocale":"ja","term":"スリッページ","aka":["Slippage"],"short":"スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。","body":[[["成行注文","market-order"],"は板に並んでいる注文を順番に消化するため、注文量が最良価格の数量を超えると、より不利な価格でも約定します。また、注文を出してから約定するまでの間に価格が動くことでも、スリッページは生じます。"],["スリッページが大きくなりやすいのは、板が薄い小型銘柄、取引の少ない時間帯、重要な発表直後の急変時です。",["分散型取引所","dex"],"（DEX）では、",["流動性プール","liquidity-pool"],"の規模に対して取引額が大きいほど価格が不利になる「プライスインパクト」も加わります。"],["対策は、",["指値注文","limit-order"],"を使う、注文を分割する、",["流動性","liquidity"],"の高いペアを選ぶことです。DEXでは「スリッページ許容値」を設定でき、これを超えると取引は失敗します。許容値を大きくしすぎると、不利な価格で約定したり、",["サンドイッチ攻撃","mev"],"と呼ばれる手口の標的になったりするおそれがあります。"]],"example":"例えば、画面に表示されていたSOLの価格が150ドルで、成行で200 SOLを買ったところ、平均約定価格が151.2ドルだったとします。スリッページは1 SOLあたり1.2ドル、率にすると0.8%で、合計240ドルの追加コストです。注文を数回に分けて指値で出していれば、このコストを抑えられた可能性があります。","mistakes":["板の薄い銘柄で、一度に大きな成行注文を出すこと。","DEXのスリッページ許容値を必要以上に大きく設定すること。","重要な発表の直後に、価格を確認せず成行で売買すること。"],"faq":[{"q":"スリッページが有利な方向に働くこともありますか？","a":"あります。注文中に価格が有利な方向へ動けば、想定より良い価格で約定することもあり、これをポジティブスリッページと呼ぶことがあります。"},{"q":"DEXのスリッページ許容値はどれくらいに設定すべきですか？","a":"銘柄の流動性によって異なります。主要ペアでは小さめで足りることが多く、流動性の低いトークンほど大きな値が必要になりますが、その分不利な約定のリスクも増えます。"}],"title":"スリッページとは？原因と防ぐ方法を解説","description":"スリッページの意味と発生する原因、成行注文やDEXでの影響、許容値の設定などスリッページを抑える方法を解説します。","related":[["bid-ask-spread","スプレッド（売買価格差）","スプレッドとは、板の最良買い気配（ビッド）と最良売り気配（アスク）の価格差のことで、売買のたびに実質的にかかるコストの一つです。"],["market-order","成行注文","成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。"],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"],["amm","AMM（自動マーケットメーカー）","AMM（自動マーケットメーカー）とは、板で売り手と買い手を突き合わせる代わりに、流動性プールと数式で自動的に価格を決めて取引を成立させる仕組みです。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"画面に表示された価格が、なぜ約定価格と違うのか？"},"coin":null,"tool":"/rates","cta":false},"trailing-stop":{"slug":"trailing-stop","cat":"trading","en":"Trailing stop","contentLocale":"ja","term":"トレーリングストップ","aka":["トレイリングストップ","Trailing stop"],"short":"トレーリングストップとは、価格が有利な方向に動くと損切り価格も自動で追いかけて移動し、反転して一定幅戻ったときに決済する注文です。","body":[["設定するのは、最高値からどれだけ下がったら決済するかを示す「追跡幅」で、金額やパーセンテージで指定します。",["買いポジション","long-and-short"],"の場合、価格が上がるたびに発動価格も引き上げられ、価格が下がっても発動価格は下がりません。"],"利点は、上昇トレンドが続く限り利益を伸ばしつつ、反転したときにある程度の利益を守れることです。目標価格を決めずに利益を追いかけたいときに向いています。多くの取引所では、追跡を開始する価格（アクティベーション価格）も設定できます。",["重要なのは追跡幅の設定です。狭すぎると普段の値動きですぐに発動し、広すぎると利益を大きく戻してから決済されます。",["ボラティリティ","volatility"],"の大きい銘柄ほど、幅を広めに取る必要があります。発動後は成行で決済されることが多く、急変時は",["スリッページ","slippage"],"が生じます。仕様は取引所ごとに異なるため、事前に確認しましょう。"]],"example":["例えば、BTCを60,000ドルで買い、追跡幅5%のトレーリングストップを設定したとします。価格が70,000ドルまで上がると、発動価格は70,000 × 0.95 = 66,500ドルに引き上げられます。その後66,500ドルまで下がると決済され、1 BTCあたり6,500ドルの利益が確定します。買った直後に価格が下がった場合は、60,000 × 0.95 = 57,000ドルで",["損切り","stop-loss"],"されます。"],"mistakes":["値動きに対して追跡幅を狭くしすぎ、小さな押し目ですぐに決済されること。","価格が下がると発動価格も一緒に下がると誤解すること。","ポジションを手動で決済した後、トレーリングストップの注文を残したままにすること。"],"faq":[{"q":"トレーリングストップの幅はどれくらいにすべきですか？","a":"銘柄の普段の値動きの大きさを基準にします。値動きの大きいアルトコインでは、ビットコインより広めの幅が必要になることが多いです。"},{"q":"日本の取引所でもトレーリングストップは使えますか？","a":"対応状況は取引所ごとに異なります。使えない場合は、逆指値の価格を自分で段階的に引き上げることで、似た効果を得られます。"}],"title":"トレーリングストップとは？仕組みと設定のコツ","description":"トレーリングストップの仕組み、追跡幅の決め方、損切りと利益確定を自動化する使い方を具体例で解説します。","related":[["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"],["take-profit","利益確定注文（テイクプロフィット）","利益確定注文（テイクプロフィット）とは、価格が目標の水準に達したときに自動で決済し、含み益を実際の利益として確定させる注文です。"],["stop-limit-order","ストップリミット注文","ストップリミット注文とは、価格がトリガー価格（ストップ価格）に達したときに、あらかじめ指定した価格で指値注文を自動発注する注文方法です。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"利確と損切りは計画であって、保険ではない"},"coin":null,"tool":null,"cta":false},"mark-price":{"slug":"mark-price","cat":"derivatives","en":"Mark price","contentLocale":"ja","term":"マーク価格","aka":["マークプライス","評価価格","mark price"],"short":"マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。","body":[["先物の",["最終取引価格","last-price"],"は、薄い板に大きな注文が入ると一瞬だけ大きく動くことがあります。この価格で清算を判定すると、実態のない値動きで多くのポジションが清算されてしまいます。そのため取引所は、",["インデックス価格","index-price"],"（複数の",["現物取引","spot-trading"],"所の加重平均）をベースに、",["資金調達率","funding-rate"],"や",["先物と現物の価格差","futures-basis"],"を加味したマーク価格を使います。"],["マーク価格は、",["含み損益（未実現損益）","unrealized-pnl"],"の計算と清算の判定に使われるのが一般的です。そのため、チャート上で最終取引価格が清算価格に触れても、マーク価格が届いていなければ清算されないことがあります。逆に、取引所の板が静かでも現物市場が大きく動けば、マーク価格が動いて清算されることもあります。"],"計算方法は取引所によって異なり、インデックスの構成取引所や平滑化の方法も違います。取引画面では最終取引価格とマーク価格を切り替えて表示できることが多いので、レバレッジ取引では両方を確認する習慣をつけてください。"],"example":"BTCのロングを持ち、清算価格が59,000 USDTだとします。ある取引所の先物で大口の成行売りが入り、最終取引価格が一瞬58,500 USDTまで下がりました。しかし複数の現物取引所の価格をもとにしたインデックス価格は60,000 USDTのままで、マーク価格も約60,010 USDTでした。清算の判定はマーク価格で行われるため、このポジションは清算されません。","mistakes":["チャートの最終取引価格だけを見て、清算されるかどうかを判断する。","含み損益の表示がマーク価格で計算されていることを知らず、決済時の損益と違って驚く。","逆指値の発動基準を最終取引価格とマーク価格のどちらにするかを確認せずに設定する。"],"faq":[{"q":"マーク価格と最終取引価格の違いは何ですか？","a":"最終取引価格はその取引所で直近に約定した価格、マーク価格は清算や含み損益の判定に使われる公正価格です。急変時にはこの2つが大きく離れることがあります。"},{"q":"なぜ清算にマーク価格が使われるのですか？","a":"1つの取引所での一時的な急変や価格操作による不当な清算を防ぐためです。複数の現物価格をもとにするため、より安定した値になります。"}],"title":"マーク価格とは？最終取引価格との違いと清算判定","description":"マーク価格の意味と計算の考え方、最終取引価格やインデックス価格との違い、清算判定に使われる理由を具体例で解説します。","related":[["index-price","インデックス価格","インデックス価格とは、複数の主要な現物取引所の価格を加重平均して算出した、その暗号資産の現物の基準価格のことで、マーク価格や資金調達率の計算に使われます。"],["liquidation-price","清算価格（ロスカット価格）","清算価格（ロスカット価格）とは、マーク価格がその水準に達するとポジションが強制ロスカットされる価格のことで、レバレッジと維持証拠金率によって決まります。"],["last-price","最終取引価格（直近約定価格）","最終取引価格（直近約定価格）とは、その取引所の板で最後に売買が成立した価格のことで、取引画面やチャートに表示される通常の「現在値」です。"],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"強制決済（清算）：強制終了のボタンを押したのは誰か"},"coin":null,"tool":"/funding-rates","cta":false},"instant-convert":{"slug":"instant-convert","cat":"exchange-features","en":"Convert (instant swap)","contentLocale":"ja","term":"コンバート（簡単交換）","aka":["Convert","簡単交換","販売所","インスタントスワップ"],"short":"コンバートとは、取引所が提示した価格で、板を使わずにある暗号資産を別の暗号資産やステーブルコインにワンタップで交換できる機能のことです。","body":["海外取引所では「Convert」や「簡単交換」、日本の取引所では「販売所」がこれに近い仕組みです。交換する数量を入力すると、取引所が数秒間有効な価格を提示し、確定ボタンを押すとその価格で交換されます。注文方法や板の読み方を知らなくても使えるのが利点です。",["多くの場合、明示的な手数料は無料と表示されますが、提示価格には取引所の取り分（",["スプレッド","bid-ask-spread"],"）が含まれています。板で",["成行注文","market-order"],"を出す場合と比べて、実質的なコストが高くなることがあります。"],["少額をすぐに交換したいときや、板の薄いマイナー銘柄を交換したいときには便利です。一方、金額が大きい場合は、板取引（取引所）で",["指値注文","limit-order"],"を使うほうがコストを抑えられることが多いので、両方の価格を見比べる習慣をつけましょう。"]],"example":"あなたが0.5 ETHをUSDTに換えたいとします。板の最良買い価格が3,000 USDTなら、成行で売ると約1,500 USDTを受け取れ、取引手数料0.1%を引くと約1,498.5 USDTです。一方、コンバートでは手数料無料と表示されますが、提示価格が2,985 USDTだったとすると、受け取れるのは1,492.5 USDTで、差は約6 USDTです。0.5 ETH程度なら大きな差ではありませんが、10 ETHを交換すると約120 USDTの差になります。数字は説明用で、実際のスプレッドは取引所や時間帯によって変わります。","mistakes":["「手数料無料」という表示だけを見て、スプレッドに含まれるコストに気づかない。","大きな金額を毎回コンバートで交換し、板取引との差額を積み重ねてしまう。","提示価格の有効時間が切れて再提示された価格を確認せずに確定する。"],"faq":[{"q":"コンバートと現物取引はどちらが安いですか？","a":"一般的には、板を使った現物取引のほうがコストを抑えやすいです。ただし板の薄い銘柄や少額の場合は、コンバートの方が手軽で差も小さいことがあります。"},{"q":"コンバートの手数料はどこにかかっていますか？","a":"多くの場合、別途の手数料ではなく、提示される交換レートの中にスプレッドとして含まれています。板の価格と比べることで、実質的なコストがわかります。"}],"title":"コンバートとは？簡単交換の仕組みと隠れたコスト","description":"取引所のコンバート（簡単交換・販売所）の意味と仕組み、手数料無料の表示とスプレッドの関係、板取引とのコスト比較を解説します。","related":[["spot-trading","現物取引（スポット取引）","現物取引（スポット取引）とは、暗号資産をその時点の価格で実際に売買し、買った資産をそのまま受け取って保有する取引のことです。"],["market-order","成行注文","成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。"],["bid-ask-spread","スプレッド（売買価格差）","スプレッドとは、板の最良買い気配（ビッド）と最良売り気配（アスク）の価格差のことで、売買のたびに実質的にかかるコストの一つです。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"初めての現物取引：100から0.002 BTCへ"},"coin":null,"tool":null,"cta":false},"tokenized-stocks":{"slug":"tokenized-stocks","cat":"tokenized-assets","en":"Tokenized stocks","contentLocale":"ja","term":"トークン化株式","aka":["株式トークン","トークン化された株","tokenized stocks"],"short":"トークン化株式とは、実際の株式や株式に連動する権利をブロックチェーン上のトークンとして発行し、暗号資産と同じように保有や送金ができるようにしたものです。","body":[["代表的な仕組みは、発行体やカストディ業者が実際の株式を保有し、その株式1株などに対応するトークンを発行するものです。Backed FinanceのxStocksなどがその一例で、一部の",["暗号資産","cryptocurrency"],"取引所やDEXで取引できるようになっています。"],["株式市場が閉まっている時間帯にも取引できる場合があることや、",["ステーブルコイン","stablecoin"],"で少額から買えることが特徴です。一方で、トークンの保有者が必ずしも株主として議決権を持つわけではなく、配当の扱いも商品によって異なります。"],"トークン化株式は、規制の扱いが国ごとに大きく異なります。多くの商品は米国居住者などには販売されておらず、日本でも金融商品取引法との関係で取扱いは限られます。発行体の信用、裏付けとなる株式の保管方法、償還の条件を確認することが大切です。"],"example":"ある米国株が1株200ドルで取引されているとします。あなたがステーブルコインで100 USDCを使い、その株式に連動するトークンを0.5枚購入しました。株価が220ドルに10%上がれば、トークンの価値も理論上は約110ドルになります。ただし米国市場が閉まっている週末に取引すると、裏付けとなる株式の価格が更新されないため、トークンの価格は需給によって一時的に200ドル相当から上下に離れることがあります。たとえば週末に1枚210ドルで買い、月曜の市場で株価が200ドルのまま始まれば、約5%割高に買ったことになります。","mistakes":["トークンを保有すれば、実際の株主と同じように議決権や配当を受け取れると思い込む。","株式市場の休場中にトークンの価格が裏付けの株価から離れることを考慮しない。","発行体やカストディ業者が破綻した場合のリスクを確認しない。"],"faq":[{"q":"トークン化株式と株式の無期限先物の違いは何ですか？","a":"トークン化株式は裏付けとなる株式を保有する発行体がいる現物型の商品です。株式の無期限先物は、株価に連動する差金決済の契約で、株式そのものは保有されません。"},{"q":"トークン化株式で配当はもらえますか？","a":"商品によって異なります。配当相当額をトークンで受け取れる仕組みもあれば、価格に反映されるだけのものもあるため、発行体の説明を確認してください。"}],"title":"トークン化株式とは？仕組みとリスクを解説","description":"トークン化株式の意味と仕組み、実際の株式との違い、議決権や配当の扱い、休場中の価格のずれなど注意点を解説します。","related":[["stock-perpetuals","株式の無期限先物（株式パーペチュアル）","株式の無期限先物とは、個別株や株価指数の価格に連動し、満期のない先物契約として証拠金とレバレッジで取引できるデリバティブ商品のことです。"],["real-world-assets","RWA（現実資産のトークン化）","RWAとは、国債、株式、不動産、金、貸付債権など、ブロックチェーンの外にある現実の資産を、トークンとしてブロックチェーン上で表現したもの、またはその分野のことです。"],["spot-bitcoin-etf","ビットコイン現物ETF","ビットコイン現物ETFとは、運用会社が実際のビットコインを保有し、その価格に連動するよう設計された、証券取引所に上場している投資信託のことです。"],["usdc","USDC（USDコイン）","USDCとは、米国のCircle社が発行する米ドル連動型のステーブルコインで、現金と米国短期国債などを裏付けに1 USDCが約1ドルになるよう設計されています。"]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
